def validate_brackets(s: str) -> bool:
    """Check whether a string of brackets is balanced.

    Args:
        s: The string containing only bracket characters.

    Returns:
        True if brackets are balanced, False otherwise.

    Example:
        >>> validate_brackets("([]{})")
        True
    """
    if not isinstance(s, str):
        raise ValueError("Input must be a string")
    stack = []
    bracket_map = {')': '(', '}': '{', ']': '['}
    for char in s:
        if char in "({[":
            stack.append(char)
        elif char in ")}]":
            if not stack or stack.pop() != bracket_map[char]:
                return False
    return len(stack) == 0
