def group_by_key(data: list[dict], key: str) -> dict:
    """Group a list of dictionaries by the value of a given key.

    Args:
        data: List of dictionaries to group.
        key: The key to group by.

    Returns:
        A dictionary where keys are the unique values of the given key and
        values are lists of dictionaries with that key value.

    Example:
        >>> data = [{'name': 'Alice', 'age': 30}, {'name': 'Bob', 'age': 30}, {'name': 'Charlie', 'age': 25}]
        >>> group_by_key(data, 'age')
        {30: [{'name': 'Alice', 'age': 30}, {'name': 'Bob', 'age': 30}], 25: [{'name': 'Charlie', 'age': 25}]}
    """
    if not data:
        return {}
    if not all(isinstance(item, dict) for item in data):
        raise ValueError("All items in data must be dictionaries")
    if not all(key in item for item in data):
        raise ValueError(f"Key '{key}' not found in all dictionaries")

    result = {}
    for item in data:
        k = item[key]
        if k not in result:
            result[k] = []
        result[k].append(item)
    return result
